#!/usr/bin/env node
/**
 * AURA — the Listening sign shows every time
 *
 *   Saying "Hey AURA, next song" in one go used to skip the "Listening…" sign (it only showed after
 *   a pause). Now it shows as soon as Windows hears "Hey AURA", while you're still talking.
 *
 * How to use:  node aura-voice-bubble-setup.cjs      (in your AURA project folder)
 * To undo:     node aura-voice-bubble-setup.cjs --undo
 */
"use strict";
